# Build the test output from the inferred component-drop rule.
H,W=30,24
g=[[7]*W for _ in range(H)]
# Large panel: color 2, with border marker 6 on the sides
for r in range(16,24):
    for c in range(W):
        g[r][c] = 6 if c in (0,W-1) else 2
# Bottom panel: color 9, with border marker 5 on the sides
for r in range(25,30):
    for c in range(W):
        g[r][c] = 5 if c in (0,W-1) else 9
# Component of color 2 at bbox rows 6..8, cols 14..17; drop to panel bottom row 23.
for r,cells in [(21,[15,16]),(22,[14,15,16,17]),(23,[15,16])]:
    for c in cells: g[r][c]=6
# Separate 2x2 component at cols 19..20, dropped to the same bottom edge.
for r in (22,23):
    for c in (19,20): g[r][c]=6
# Color-9 component bbox rows 10..12, cols 4..10; drop to bottom row 29.
for r in (27,28):
    for c in range(4,11): g[r][c]=5
for c in (4,5,9,10): g[29][c]=5
print('\n'.join(' '.join(map(str,row)) for row in g))
